import struct, os, glob, json
from pathlib import Path

def decode_lnk(path):
    data = Path(path).read_bytes()
    out = {"file": os.path.basename(path), "size": len(data)}
    # strings
    strings = []
    # utf16
    i=0
    while i < len(data)-3:
        if data[i] != 0 and data[i+1]==0:
            chars=[]
            j=i
            while j+1 < len(data) and data[j+1]==0 and 32<=data[j]<127:
                chars.append(chr(data[j])); j+=2
            if len(chars)>=4:
                strings.append(''.join(chars)); i=j
            else:
                i+=1
        else:
            i+=1
    ascii_s=[]
    i=0
    while i < len(data):
        if 32<=data[i]<127:
            j=i
            while j<len(data) and 32<=data[j]<127:
                j+=1
            if j-i>=4:
                ascii_s.append(data[i:j].decode('ascii'))
            i=j
        else:
            i+=1
    out['utf16'] = strings
    out['ascii'] = ascii_s
    return out

