import zipfile, xml.etree.ElementTree as ET
from datetime import datetime, timedelta
z=zipfile.ZipFile('work/extracted/s83fd02/vault/Spending.xlsx')
root=ET.fromstring(z.read('xl/sharedStrings.xml'))
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
ss=[]
for si in root.findall('m:si', ns):
    texts=list(si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
    ss.append(''.join(t.text or '' for t in texts))
sheet=ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
rows=[]
for row in sheet.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheetData'):
    cells={}
    for c in row:
        ref=c.attrib['r']
        col=''.join(x for x in ref if x.isalpha())
        v=c.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v')
        if v is None: continue
        if c.attrib.get('t')=='s':
            cells[col]=ss[int(v.text)]
        else:
            cells[col]=v.text
    if cells:
        a=cells.get('A')
        if a and a.replace('.','').isdigit():
            try:
                cells['A']=xl(float(a))
            except: pass
        print(cells.get('A'), '|', cells.get('B'), '|', cells.get('C'))
